def predict(board_lines, action):
    idx = None
    for i, snap in enumerate(SNAPS):
        if [''.join(r) for r in snap] == list(board_lines):
            idx = i
            break
    if idx is None or idx not in DIFFS:
        return list(board_lines)
    b = [list(r) for r in board_lines]
    for (r, c, ch) in DIFFS[idx]:
        b[r][c] = ch
    return [''.join(r) for r in b]
